DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT113-S4-Q3$batch08$ AND q.stimulus=$batch08$An instructor presented two paintings to a class. She said that the first had hung in prestigious museums but the second was produced by an unknown amateur. Each student was asked which painting was better. Everyone selected the first. The instructor later presented the same two paintings in the same order to a different class. This time she said that the first was produced by an unknown amateur but the second had hung in prestigious museums. In this class, everyone said that the second painting was better.$batch08$ AND q.prompt=$batch08$The statements above, if true, most strongly support which one of the following?$batch08$ AND q.correct_choice=$batch08$D$batch08$) THEN RAISE EXCEPTION 'Question changed: PT113-S4-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch08$PT113-S4-Q3$batch08$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT113-S4-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT113-S4-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Same two paintings, same order, two classes. Class one was told painting 1 hung in museums and painting 2 was by an amateur: everyone picked painting 1. Class two was told the reverse: everyone picked painting 2.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Pause and infer. The paintings never changed. Only the story changed, and the verdict flipped with it. So what the students were told made a difference to at least some of them.$batch08$), (2, $batch08$Goal$batch08$, $batch08$Some students' judgments were swayed by what they were told about the paintings.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT113-S4-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$This is the most popular wrong answer. One comparison against one museum painting tells us nothing about whether students would dislike *any* amateur work.$batch08$), ($batch08$B$batch08$, $batch08$The two classes heard conflicting stories, so some claims were false. But that doesn't mean *none* were true.$batch08$), ($batch08$C$batch08$, $batch08$Preferring one museum painting over one amateur painting says nothing about liking most paintings in any museum.$batch08$), ($batch08$D$batch08$, $batch08$Same paintings, opposite verdicts, and the only change was the story. "Some" is all we need, and the flip gives us that.$batch08$), ($batch08$E$batch08$, $batch08$We have no idea what students would say with no information. Maybe they'd all pick the same one.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT113-S4-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
